used_sources = {x['sourceId'] for x in updated_claims}
updated_sources = [s for s in base['sources'] + new_sources if s['sourceId'] in used_sources]
excluded = sorted(set(base['excludedClaimIds']) | set(crohn_only))
updated = {'version':'uc-prototype-v2','createdAt':datetime.now(timezone.utc).isoformat(),'intendedUse':'informational UC evidence prototype only','sources':updated_sources,'claims':updated_claims,'excludedClaimIds':excluded,'limitations':['Human review and approval fields remain blank; no source or claim is approved.','The 15 Crohn’s-only claims from the prior prototype remain excluded from UC retrieval.','ESR remains an unresolved UC-specific evidence gap in this bounded run; no IBD-general or Crohn’s-only ESR claim was relabeled as UC evidence.','Guideline recommendations and trial results are informational, not diagnosis, flare prediction, or individualized treatment advice.','Some guideline articles are represented by public official summaries or PubMed abstracts; full text, licensing, and local Canada/US implementation require review.']}
(ROOT/'ibd-uc-evidence-prototype-v2.json').write_text(json.dumps(updated,indent=2,ensure_ascii=False)+'\n')

areas=['fecal_calprotectin','crp','esr','mucosal_healing','colonoscopy','intestinal_ultrasound','biologics','jak_inhibitors','symptoms_vs_inflammation']
def area_counts(claims):
    return {a:sum(1 for x in claims if a in (str(x.get('topic'))+';'+str(x.get('outcomeType'))+';'+str(x.get('diseaseContext'))).lower()) for a in areas}
before=area_counts(uc_existing); after=area_counts(updated_claims)
summary={'version':'uc-prototype-v2','activeSources':len(updated_sources),'includedClaims':len(updated_claims),'excludedClaims':len(excluded),'priorUcEligibleClaims':len(uc_existing),'newUcClaims':len(new_claims),'priorCrohnOnlyExclusions':len(crohn_only),'coverageBefore':before,'coverageAfter':after,'unresolvedGaps':['ESR'],'tests':'pending'}
(ROOT/'uc-evidence-summary-v2.json').write_text(json.dumps(summary,indent=2)+'\n')
(ROOT/'uc-evidence-exclusions-v2.json').write_text(json.dumps({'version':'uc-prototype-v2','excludedClaimIds':excluded,'priorCrohnOnlyExcludedClaimIds':sorted(crohn_only),'reason':'Crohn’s-only claims are retained in the audit boundary and excluded from UC retrieval; prior prototype exclusions remain excluded.','esrStatus':'unresolved_not_relabelled'},indent=2)+'\n')
report=f'''# UC evidence companion extension — v2\n\nAdded {len(new_claims)} UC-specific claims from six bounded public sources and preserved the existing {len(crohn_only)} Crohn’s-only retrieval exclusions. No human approvals were recorded.\n\n- Prior prototype: 20 sources, 49 claims\n- Updated UC export: {len(updated_sources)} active sources, {len(updated_claims)} UC-eligible claims\n- New UC claims: {len(new_claims)}\n- Crohn’s-only claims retained as exclusions: {len(crohn_only)}\n- Prior excluded IDs retained: {len(base['excludedClaimIds'])}\n\n## Coverage before and after\n\n{json.dumps({'before':before,'after':after},indent=2)}\n\nCoverage counts are tagged claims, not clinical completeness.\n\n## Unresolved gaps\n\n- ESR remains unresolved as a UC-specific claim. No general IBD or Crohn’s-only evidence was upgraded to UC-specific evidence.\n- Some guideline evidence is represented by public summaries or abstracts; full text and licensing require human review.\n- Canada/US regulatory, formulary, and local-care applicability remains to be checked.\n- No diagnosis, flare prediction, personalized treatment, or RAG/application implementation was performed.\n\nAll sources and claims remain pending human review.\n'''
(ROOT/'uc-evidence-extension-report.md').write_text(report)
print(json.dumps({'sources':len(updated_sources),'claims':len(updated_claims),'newClaims':len(new_claims),'crohnOnlyExcluded':len(crohn_only),'coverageAfter':after},indent=2))
